class ProcessSaleService_AutoGenerated {
  /*SystemVariable Start*/
  CurrentCashDesk: CashDesk;
  CurrentStore: Store;
  /*SystemVariable End*/

  /*find an item with provided barcode,
   *if current sale exists and not complete
   *and the item exists and the stock number is greater than 0, create a sales line item
   *and this sale line will be used in other operation.
   *the current sale will include this sale line and the sale line is belong to the current sale.
   *the sale line's quantity is provided quantity and the item stock number will minus the quantity.
   *then caculate the sale line subamount is the item price multiply the quantity.
   *don't forget to save the sale line.
   **/
  enterItem(barcode: number, quantity: number): boolean {
    /*Definition Start*/
    let currentItem: Item = l({
      logic: () =>
        getRepository(Item).find(
          (i: any) =>
            l({
              logic: () => i.Barcode === barcode,
              description: "i.Barcode=barcode",
            }).build().pass,
        ),
      description: "Item.allInstance()->any(i|i.Barcode=barcode)",
    }).build().pass;
    let activeSale: Sale = l({
      logic: () => this.currentSale,
      description: "self.currentSale",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(this.currentSale) === false,
        description: "self.currentSale.oclIsUndefined()=false",
      })
        .and({
          logic: () => this.currentSale.IsComplete === false,
          description: "self.currentSale.IsComplete=false",
        })
        .and({
          logic: () => getRepository(Item).includes(currentItem),
          description: "Item.allInstance()->includes(currentItem)",
        })
        .and({
          logic: () => currentItem.StockNumber >= quantity,
          description: "currentItem.StockNumber>=quantity",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newLineItem: SalesLineItem;
    return l({
      execute: () => (newLineItem = new SalesLineItem()),
      description: "newLineItem.oclIsNew()",
    })
      .and({
        execute: () => getRepository(SalesLineItem).push(newLineItem),
        description: "SalesLineItem.allInstance()->includes(newLineItem)",
      })
      .and({
        execute: () => (newLineItem.BelongedItem = currentItem),
        description: "newLineItem.BelongedItem=currentItem",
      })
      .and({
        execute: () => (newLineItem.Quantity = quantity),
        description: "newLineItem.Quantity=quantity",
      })
      .and({
        execute: () => (newLineItem.Subamount = currentItem.Price * quantity),
        description: "newLineItem.Subamount=currentItem.Price*quantity",
      })
      .and({
        execute: () =>
          (currentItem.StockNumber = currentItem.StockNumber - quantity),
        description: "currentItem.StockNumber=currentItem.StockNumber-quantity",
      })
      .and({
        execute: () => activeSale.ContainedSalesLine.push(newLineItem),
        description: "activeSale.ContainedSalesLine->includes(newLineItem)",
      })
      .and({
        execute: () => (newLineItem.BelongedSale = activeSale),
        description: "newLineItem.BelongedSale=activeSale",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { ProcessSaleService_AutoGenerated };

